const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'u = x / h' },
      { kind: 'text', payload: 'u = 0' },
      { kind: 'text', payload: 'u = 1/2' },
      { kind: 'text', payload: 'u = 1' },
      { kind: 'text', payload: '瓶口基准线（保持水平）' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: '位移 x = u·h，木塞底部到基准线距离 =（1 - u）·h，三段按真实比例绘制（示意图）' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var margin = W * 0.06;
    var panelW = (W - 2 * margin) / 3;
    var yM = H * 0.55;
    var ch = H * 0.20;
    var cw = Math.min(panelW * 0.40, H * 0.20);
    var wt = Math.max(6, W * 0.012);
    var gap = Math.max(2, W * 0.005);
    var iw = cw / 2 + gap;
    var nd = ch + H * 0.06;
    var baseY = yM + nd;
    var slabH = Math.max(8, H * 0.018);
    var neckBottom = baseY + slabH;
    var us = [0, 0.5, 1];
    var paths = [];
    var children = [];

    function rect(x0, y0, x1, y1) {
      return [['M', x0, y0], ['L', x1, y0], ['L', x1, y1], ['L', x0, y1], ['Z']];
    }

    children.push({
      type: 'label', contentId: metrics[0].contentId,
      anchor: { x: W / 2, y: H * 0.05 },
      hAlign: 'center', vAlign: 'top', color: '#26354A'
    });

    for (var i = 0; i < 3; i++) {
      var cx = margin + panelW * i + panelW / 2;
      var u = us[i];
      var cb = yM + (1 - u) * ch;
      var ct = cb - ch;
      var idWl = 'wl' + i;
      var idWr = 'wr' + i;
      var idBs = 'bs' + i;
      var idCk = 'ck' + i;

      paths.push({ id: idWl, commands: rect(cx - iw - wt, yM, cx - iw, neckBottom) });
      paths.push({ id: idWr, commands: rect(cx + iw, yM, cx + iw + wt, neckBottom) });
      paths.push({ id: idBs, commands: rect(cx - iw - wt, baseY, cx + iw + wt, neckBottom) });
      paths.push({ id: idCk, commands: rect(cx - cw / 2, ct, cx + cw / 2, cb) });

      children.push({ type: 'path', pathId: idWl, fill: '#DCE8F4', stroke: { width: 2 } });
      children.push({ type: 'path', pathId: idWr, fill: '#DCE8F4', stroke: { width: 2 } });
      children.push({ type: 'path', pathId: idBs, fill: '#C9DBEB', stroke: { width: 2 } });
      children.push({ type: 'path', pathId: idCk, fill: '#DFB98A', stroke: { width: 2 } });
      children.push({
        type: 'label', contentId: metrics[i + 1].contentId,
        anchor: { x: cx, y: neckBottom + H * 0.03 },
        hAlign: 'center', vAlign: 'top', color: '#26354A'
      });
    }

    paths.push({ id: 'baseline', commands: [['M', margin * 0.5, yM], ['L', W - margin * 0.5, yM]] });
    children.push({ type: 'path', pathId: 'baseline', fill: '#6B7C93', stroke: { width: 2, dash: [7, 6] } });
    children.push({
      type: 'label', contentId: metrics[4].contentId,
      anchor: { x: margin * 0.5, y: yM - H * 0.015 },
      hAlign: 'left', vAlign: 'bottom', color: '#6B7C93'
    });

    var cx1 = margin + panelW + panelW / 2;
    var ax = cx1 - iw - wt - Math.max(14, W * 0.02);
    var ay0 = yM;
    var ay1 = yM + ch / 2;
    paths.push({ id: 'xarrow', commands: visualSdk.arrow(ax, ay0, ax, ay1) });
    children.push({ type: 'path', pathId: 'xarrow', fill: '#B4553A', stroke: { width: 1.5 } });
    children.push({
      type: 'label', contentId: metrics[5].contentId,
      anchor: { x: ax - Math.max(4, W * 0.008), y: (ay0 + ay1) / 2 },
      hAlign: 'right', vAlign: 'middle', color: '#B4553A'
    });

    children.push({
      type: 'label', contentId: metrics[6].contentId,
      anchor: { x: W / 2, y: H - H * 0.015 },
      hAlign: 'center', vAlign: 'bottom', color: '#4A5A6E'
    });

    return {
      schemaVersion: 1,
      sceneId: 'cork-pull-stages',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
